import { tv, type VariantProps } from "@/lib/beton/tv";

export const teamGrid = tv({
  slots: {
    list: "grid gap-6",
    item: "flex h-full flex-col gap-3 border-3 border-border bg-raised p-5 shadow-sm",
    portrait: "flex items-center gap-4",
    name: "font-display text-h4 font-extrabold text-foreground",
    role: "font-mono text-xs font-bold tracking-widest uppercase",
    bio: "text-pretty text-sm text-foreground",
    links: "mt-auto flex flex-wrap items-center gap-3 pt-2",
  },
  variants: {
    columns: {
      2: { list: "sm:grid-cols-2" },
      3: { list: "sm:grid-cols-2 lg:grid-cols-3" },
      4: { list: "sm:grid-cols-2 lg:grid-cols-4" },
    },
  },
  defaultVariants: {
    columns: 3,
  },
});

export type TeamGridVariants = VariantProps<typeof teamGrid>;

import { teamGrid, type TeamGridVariants } from "@/lib/beton/recipes/team-grid.recipe";
import type { ReactNode } from "react";
import { Section, type SectionProps } from "@/components/ui/beton/section";

export interface TeamMember {
  /** Their name. */
  name: ReactNode;
  /** What they do. */
  role: ReactNode;
  /** A line or two about them. */
  bio?: ReactNode;
  /** A picture or an avatar. */
  portrait?: ReactNode;
  /** Links to wherever they are. */
  links?: ReactNode;
}

export interface TeamGridProps extends Omit<SectionProps, "children">, TeamGridVariants {
  /** The people, in order. */
  members: TeamMember[];
  /** The heading level of each name. One below the section heading. */
  itemHeadingLevel?: 3 | 4 | 5;
  /** Classes for the grid itself. */
  listClassName?: string;
}

/** Who made it, with faces and roles. */
export function TeamGrid({
  members,
  columns = 3,
  itemHeadingLevel = 3,
  listClassName,
  ...props
}: TeamGridProps) {
  const styles = teamGrid({ columns });
  const Heading = `h${itemHeadingLevel}` as const;

  return (
    <Section {...props}>
      <ul className={styles.list({ class: listClassName })}>
        {members.map((member, index) => (
          <li key={index} className={styles.item()}>
            <div className={styles.portrait()}>
              {member.portrait}
              <div>
                <Heading className={styles.name()}>{member.name}</Heading>
                <p className={styles.role()}>{member.role}</p>
              </div>
            </div>
            {member.bio ? <p className={styles.bio()}>{member.bio}</p> : null}
            {member.links ? <div className={styles.links()}>{member.links}</div> : null}
          </li>
        ))}
      </ul>
    </Section>
  );
}
